    "studio_eyebrow": "تطوير ألعاب مستقل",
    "studio_title": "ستوديو MazenX<span class=\"accent-dot\">.</span>",
    "studio_note": "MazenX هو ستوديو ألعاب مستقل أسسته بنفسي: أقوم بتصميم وبرمجة ونشر ألعاب أصلية بمحرك Unreal Engine لأنظمة Android وWindows. تصفح تفاصيل كل لعبة ودوري فيها بالأسفل.",
    "studio_link": "زيارة صفحة MazenX على LinkedIn ↗",
    "vlabel_kix": "MAZENX / UNREAL ENGINE",
    "game_kix_topline": "01 — لعبة مستقلة",
    "game_kix_title": "Crazy Kix",
    "game_kix_summary": "لعبة منصات وحركة على Unreal Engine تعتمد على القفز السريع، تجاوز العقبات والمدافع، والهروب من الطائرات المسيرة وهجمات الليزر.",
    "game_kix_long": "التحدي الأساسي يعتمد على سرعة الحركة واستمرار الاندفاع: تطارد الطائرات المسيرة اللاعب، ويعاقب الليزر أي تردد، وتشكل المنصات التفاعلية مسار كل مستوى. تستعرض اللعبة فيزياء الحركة سريعة الاستجابة، وسلوكيات الأعداء، والذكاء الاصطناعي.",
    "game_kix_contrib": "ابتكرت وبرمجت ونشرت لعبة Crazy Kix بالكامل تحت مظلة ستوديو MazenX: صممت ميكانيكا اللعب والمراحل، والمنصات المتحركة، والمدافع التفاعلية، ومواجهات الدرونز، وجهزت نُسخ المتاجر لنظامي Android وWindows.",
    "vlabel_bone": "MAZENX / منصات وأكشن 2D",
    "game_bone_topline": "02 — لعبة مستقلة",
    "game_bone_title": "The Bone Runner",
    "game_bone_summary": "لعبة أكشن ومنصات 2D على Unreal Engine يقاتل فيها البطل وحوش الهياكل العظمية ويتفادى فخاخ الزنازين بتوقيت ومهارة عالية.",
    "game_bone_long": "يختبر كل مستوى مهارات الحركة والقتال وسرعة البديهة. تتطلب المستويات دراسة المخاطر واختيار التوقيت الأنسب للهجوم للوصول للمخرج بسلام. تركز اللعبة على حركة الشخصيات ثنائية الأبعاد، ونظام القتال، والذكاء الاصطناعي، وتصميم الفخاخ.",
    "game_bone_contrib": "طوّرت اللعبة ونشرتها بصورة مستقلة: بنيت حلقة القتال والحركة الأساسية، ومواجهات الأعداء، ونظام الفخاخ، وتصميم مستويات الزنزانة، وجهزت نُسخ Windows وAndroid.",
    "vlabel_addiction": "MAZENX / BLUEPRINTS",
    "game_addiction_topline": "03 — لعبة مستقلة",
    "game_addiction_title": "Gambling Addiction",
    "game_addiction_summary": "لعبة ساحات قتالية مبنية بـ Blueprints في Unreal Engine، حيث تُغير الكرات السحرية العشوائية موازين التحالفات والأعداء ومسار المعركة عبر 3 أنماط قتال.",
    "game_addiction_long": "تتضمن اللعبة 3 أنماط للمواجهة: روبوتات ضد روبوتات، لاعب ضد روبوت، وروبوتات ضد لاعبين. تُسفر الكرات العشوائية عن استدعاء أو إخفاء حلفاء وأعداء، مما يخلق معارك ديناميكية غير متوقعة سواء كنت تلعب بنفسك أو تشاهد ردود فعل الذكاء الاصطناعي.",
    "game_addiction_contrib": "طوّرت فكرة اللعبة ووسعتها بشكل مستقل عبر ميكانيكا الكرات السحرية العشوائية، ونظام توليد وإزالة الحلفاء والأعداء، وتصميم الأنماط القتالية الثلاثة وتوثيق المشروع.",
    "link_ms_store": "متجر Microsoft Store ↗",
    "link_google_play": "متجر Google Play ↗",
    "link_github": "مستودع GitHub ↗",
    "about_eyebrow": "منهجية العمل",
    "about_title": "من الفكرة الأولى<br>حتى <em>الإطلاق للإنتاج.</em>",
    "about_lede": "أستمتع برحلة المنتج كاملة: فهم المشكلة وصياغة المعمارية البرمجية وتطوير تجربة الاستخدام وإطلاقها في بيئة الإنتاج بثقة وموثوقية.",
    "about_body": "تتنوع خبراتي بين برمجيات الشركات والمؤسسات، الرعاية الصحية، منصات الـ SaaS، التعليم، والترفيه. أقوم بتطوير تطبيقات متعددة المنصات باستخدام Flutter، وواجهات برمجية خلفية بـ NestJS، وميكانيكا الألعاب بمحرك Unreal Engine. ساهمت في منتجات حية، وعملت بتعاون مع مختلف التخصصات، ونشرت مكتبات برمجية على pub.dev، وأشرفت على توجيه وتدريب مهندسين واعدين.",
    "about_stat_years": "سنوات خبرة في هندسة البرمجيات",
