    "hero_eyebrow": "SOFTWARE ENTWICKLER · UNABHÄNGIGER SPIELEENTWICKLER",
    "hero_title": "Mazen EL-Gayar<br><em>Software für die Produktion.</em>",
    "hero_lede": "Senior Software Engineer mit über 4 Jahren Erfahrung in der Entwicklung produktionsreifer Produkte mit Flutter und Dart, Backend-APIs mit NestJS und Indie-Spielen in Unreal Engine.",
    "hero_explore": "Ausgewählte Arbeiten entdecken <span>↓</span>",
