    "hero_exp": "+4 JAHRE SOFTWAREENTWICKLUNG",
    "hero_orbit_caption": "ENTWICKELN · VERÖFFENTLICHEN · ITERIEREN",
    "intro_engineering": "PRODUKTENTWICKLUNG",
    "intro_platforms": "MOBILE · WEB · DESKTOP · BACKEND · GAMES",
    "intro_delivery": "END-TO-END BEREITSTELLUNG",
    "work_eyebrow": "EINE AUSWAHL MEINER PROJEKTE",
    "work_title": "Ausgewählte Arbeiten<span class=\"accent-dot\">.</span>",
    "work_note": "Plattformübergreifende Produkte für Unternehmen, Gesundheit, Bildung, Entwickler-Tools, Medien und Immobilien.",
    "vlabel_leango": "GLOBAL LEAN INDUSTRY · LEANGO SUITE",
    "proj_leango_topline": "04 — PRODUKTFAMILIE",
    "proj_leango_title": "LeanGo-Anwendungen",
    "proj_leango_summary": "Plattformübergreifende Flutter-Suite für Sicherheitspersonal, Personal- und Finanzoperationen, Gebäudemanagement und Maschinenproduktivität bei GLI (GRWAN Group).",
    "proj_leango_long": "LeanGo Eye unterstützt Sicherheitspersonal mit NFC, GPS und Funk. LeanGo FTE verwaltet Anwesenheit und Schichten. LeanGo FM überwacht Gebäude per QR-Code und SOS-Tickets. LeanGo CIL verbindet App und Web-Dashboard zur Überwachung von Maschinen. Zur Familie gehören außerdem LeanGo WMS, LeanGo E&T und das CIL-Web-Dashboard.",
    "proj_leango_contrib": "Entwicklung und Projektleitung für die LeanGo-Suite: Konzeption robuster Features, API-Integration und Koordination von Releases.",
    "vlabel_flexo": "MANDANTENFÄHIGES ERP · FLUTTER",
    "proj_flexo_topline": "03 — UNTERNEHMENSSOFTWARE",
    "proj_flexo_title": "Mandantenfähige ERP-Plattform",
    "proj_flexo_summary": "Mandantenfähiges Flutter-ERP für Zahlungen, Rechnungen und Zeiterfassung in vier individuellen Marken-Flavors.",
    "proj_flexo_long": "Gemeinsame Flutter-Codebasis konfiguriert für mehrere Unternehmenskunden mit separaten Builds für Food & Health, NDS und Gastronomie.",
    "proj_flexo_contrib": "Als Senior Flutter Developer entwickelte ich die Kernfunktionen der gemeinsamen ERP-App und lieferte vier eigenständige Releases aus.",
    "vlabel_dv": "DOCTORVOICE · GESUNDHEITSWESEN · FLUTTER + NESTJS",
    "proj_dv_topline": "01 — GESUNDHEITSWESEN",
    "proj_dv_title": "DoctorVoice",
    "proj_dv_summary": "KI-gestützte Produkte für Patienten und Ärzte mit Flutter und NestJS, einschließlich Sprache-zu-Text-Dokumentation und Berichten.",
    "proj_dv_long": "Die Plattform verbindet Produktmanagement, Design, Mobile, Web, Backend, KI und QA, um Konsultationen und Dokumentation zu optimieren.",
    "proj_dv_contrib": "Neben der Softwareentwicklung koordiniere ich QA-, KI-, Backend- und Mobile-Teams, betreue 5+ Praktikanten und bilde die Brücke zur Geschäftsführung.",
    "vlabel_penguin": "PENGUIN · EDTECH · FLUTTER",
    "proj_penguin_topline": "02 — BILDUNG",
    "proj_penguin_title": "Penguin",
    "proj_penguin_summary": "Eine saudische Online-Lernplattform mit zwei Flutter-Apps — Penguin für Schüler und Eltern, Penguin Staff für Lehrkräfte und Betreuer — auf allen Plattformen aus einer gemeinsamen Codebasis.",
    "proj_penguin_long": "Schüler folgen ihren Kursen, nehmen an Live-Videostunden mit ihren Lehrkräften im Stil von Zoom teil, erledigen Hausaufgaben, üben mit einem KI-Tutor und erhalten Zertifikate. Eltern verknüpfen sich per QR-Code mit ihren Kindern, um Hausaufgaben und Fortschritt zu verfolgen, während Lehrkräfte und Betreuer Klassen, Aufgaben und Meetings in der Staff-App verwalten. Beide Apps teilen ein Flutter-Paket für Netzwerk, Designsystem, Übersetzungen und Features und laufen auf Android, iOS, Web, macOS und Windows.",
    "proj_penguin_contrib": "Ich habe das gemeinsame Flutter-Paket beider Apps gebaut, das Laravel-Backend für Kurse, Aufgaben, Chat, Übungen und Eltern-Hausaufgaben angebunden, Echtzeit-Updates ergänzt und beide Apps mit großflächigen Layouts auf Desktop und Web gebracht. Außerdem habe ich die CI/CD-Release-Pipeline für die Stores eingerichtet.",
    "vlabel_rasid": "RASID · FELDEINSÄTZE & AUDITS · FLUTTER",
    "proj_rasid_topline": "05 — ENTERPRISE & OPERATIONS",
    "proj_rasid_title": "RASID & RASID Admin",
    "proj_rasid_summary": "Plattformübergreifende Inspektions- und Betriebsplattform mit der RASID-App und dem RASID Admin-Dashboard für Audits und Berichte.",
    "proj_rasid_long": "Umfassende Echtzeitüberwachung und Durchführung von Vor-Ort-Aufgaben. Clean Architecture garantiert schnelle Synchronisation und Offline-Verfügbarkeit.",
    "proj_rasid_contrib": "Gesamtverantwortung für die Entwicklung von RASID und RASID Admin. Konzeption der Architektur, Offline-Synchronisation und Ausbildung von 7 Absolventen in Best Practices.",
    "vlabel_pkg": "OPEN SOURCE / PUB.DEV",
    "proj_pkg_topline": "06 — ENTWICKLER-TOOLS",
    "proj_pkg_title": "Flutter-Packages",
    "proj_pkg_summary": "Wiederverwendbare Flutter- und Dart-Bibliotheken für PayPal Checkout, Asset-Codegenerierung und Lokalisierung auf pub.dev.",
    "proj_pkg_long": "Bibliotheken für die weltweite Entwickler-Community mit ausführlicher Dokumentation und stabilen Releases.",
    "proj_pkg_contrib": "Konzeption, Entwicklung, Veröffentlichung und laufende Pflege der Open-Source-Pakete auf pub.dev.",
    "vlabel_myflix": "MYFLIX PLUS · DEINE STREAMING-BIBLIOTHEK",
    "proj_myflix_topline": "07 — CROSS-PLATFORM",
    "proj_myflix_title": "MyFlix Plus + Fernbedienung",
    "proj_myflix_summary": "Ein persönlicher Streamingdienst für deine eigenen Videos: MyFlix Plus spielt und ordnet sie unter Windows, macOS, Linux, Android, Android TV und iPhone, und MyFlix Remote macht jedes Handy zur Fernbedienung.",
    "proj_myflix_long": "Plus macht aus Ordnern und Videolinks eine Bibliothek im Streaming-Stil mit Staffeln, Covern, Weiterschauen, Favoriten, Online-Untertiteln und Wiedergabeeinstellungen pro Serie. Es kann den Bildschirm spiegeln oder das Video an Handys im Netzwerk senden und ein Handy als Lautsprecher nutzen. Die Fernbedienung koppelt sich per QR-Code oder 6-stelligem Code, steuert Wiedergabe, Lautstärke, Helligkeit, Tonspur und Untertitel, lässt mehrere Handys synchron zusammen schauen und bietet Widgets, ein Touchpad und Sperrbildschirm-Steuerung.",
    "proj_myflix_contrib": "Ich habe beide Apps allein in Flutter entworfen und gebaut: den mpv-basierten Player und die Mediathek, die Cover- und Untertitelsuche, ein Kopplungsprotokoll im lokalen Netz mit Geräteverwaltung, Bildschirmspiegelung und Video-Übertragung an Handys, das Handy als Audioausgabe, synchrones gemeinsames Schauen, Unterstützung für Android TV und Widgets sowie CI/CD-Pipelines, die die Windows-App für den Microsoft Store und die Android-Apps für Google Play aus einem Git-Tag bauen und veröffentlichen.",
    "vlabel_aware": "AWARE · DIEBSTAHLALARM · FLUTTER",
    "proj_aware_topline": "08 — MOBILGERÄTESICHERHEIT",
    "proj_aware_title": "Aware",
    "proj_aware_summary": "Anti-Diebstahl-Bewegungsalarm-App, die das Smartphone bei unbeaufsichtigter Ablage mittels integrierter Sensoren und Sirenenalarm schützt.",
    "proj_aware_long": "Aware schützt das Smartphone durch Hardware-Bewegungs- und Lichtsensoren. Bei unbefugter Bewegung oder Entnahme aus der Tasche startet ein Countdown. Erfolgt keine rechtzeitige Entsperrung, ertönt ein lauter Alarm, der nur durch Nutzer-Authentifizierung gestoppt werden kann.",
    "proj_aware_contrib": "Eigenständige Konzeption, Entwicklung und Veröffentlichung von Aware im Google Play Store mit Flutter. Programmierung der Sensor-Erkennung (Bewegung, Taschenmodus), manipulationssicherer Timer und moderner Sicherheits-Benutzeroberfläche.",
    "vlabel_samsarly": "ABSCHLUSSPROJEKT · IMMOBILIEN · KI",
    "proj_samsarly_topline": "09 — ABSCHLUSSPROJEKT",
    "proj_samsarly_title": "Samsarly",
    "proj_samsarly_summary": "Kartenbasierter Immobilienmarktplatz mit KI-Preisvergleich, Token-System für Eigentümerkontakt und 6 Sprachen.",
    "proj_samsarly_long": "Ermöglicht Benutzern Immobiliensuche auf interaktiven Karten, KI-Preisanalysen und Direktkontakt in 6 Sprachen.",
    "proj_samsarly_contrib": "Entwicklung der gesamten Flutter-Anwendung: Kartenintegration, Filter, KI-Preisanalyse und Lokalisierung.",
