    "vlabel_kix": "MAZENX / UNREAL ENGINE",
    "game_kix_topline": "01 — インディーゲーム",
    "game_kix_title": "Crazy Kix",
    "game_kix_summary": "ドローンやレーザーの追撃をかわしながら、キャノンやギミックを駆使してステージを駆け抜けるスピード感あふれるアクションプラットフォーマー。",
    "game_kix_long": "テンポ良い移動物理、追跡ドローンのAI、レーザーギミック、ギミック砲台など、快適なレスポンスと手応えある難易度を追求。",
    "game_kix_contrib": "MazenXスタジオ作品として企画・開発・公開。レベルデザイン、移動ギミック、敵AI、ストア向けビルド構築を担当。",
    "vlabel_bone": "MAZENX / 2Dアクション",
    "game_bone_topline": "02 — インディーゲーム",
    "game_bone_title": "The Bone Runner",
