    "game_kix_long": "重点打磨角色位移惯性手感、追击型无人机AI寻路算法、即时机关交互与陷阱打击判定，兼顾流畅度与关卡挑战性。",
    "game_kix_contrib": "以MazenX名义独立策划、开发并上架，负责全部关卡机制、敌人行为逻辑、物理机制及多端商城构建。",
