    "game_bone_long": "运用虚幻引擎实现流畅的2D帧动画与骨骼动画、近战攻击判定、周期陷阱系统与递进式地牢关卡构造。",
    "game_bone_contrib": "独立搭建核心战斗循环、敌人AI策略、陷阱逻辑与Windows/Android双端适配部署。",
