    "game_kix_summary": "Platform d'azione frenetico in Unreal Engine in cui evitare droni da inseguimento e trappole laser sfruttando cannoni e piattaforme dinamiche.",
    "game_kix_long": "Movimento reattivo, collisioni fluide, intelligenza artificiale dei droni e sfide ambientali studiate per release fluide su mobile e PC.",
    "game_kix_contrib": "Ideato, sviluppato e pubblicato sotto l'etichetta MazenX: level design, fisica del salto, IA nemica e pacchetti di release per gli store.",
    "vlabel_bone": "MAZENX / PLATFORM D'AZIONE 2D",
    "game_bone_topline": "02 — GIOCO INDIE",
    "game_bone_title": "The Bone Runner",
    "game_bone_summary": "Platform d'azione 2D in Unreal Engine ambientato in segrete infestate da scheletri e trappole mortali da superare con tempismo millimetrico.",
    "game_bone_long": "Animazioni 2D fluide, sistema di combattimento all'arma bianca, pattern di attacco dei nemici e generazione di trappole a tempo.",
    "game_bone_contrib": "Sviluppo completo delle meccaniche di gioco, animazioni, IA nemica, design dei dungeon e ottimizzazione per PC e Android.",
    "vlabel_addiction": "MAZENX / BLUEPRINTS",
