    "studio_note": "MazenX — моя независимая игровая студия: я проектирую, программирую и публикую оригинальные игры на движке Unreal Engine для Windows и Android.",
    "studio_link": "MazenX в LinkedIn ↗",
    "vlabel_kix": "MAZENX / UNREAL ENGINE",
    "game_kix_topline": "01 — ИНДИ-ИГРА",
    "game_kix_title": "Crazy Kix",
    "game_kix_summary": "Динамичный платформер на Unreal Engine с преодолением лазерных ловушек, использованием пушек и спасением от преследующих дронов.",
    "game_kix_long": "Чуткая физика перемещения, поведение дронов с ИИ, лазерные преграды и интерактивные объекты окружения для ПК и мобильных устройств.",
    "game_kix_contrib": "Создал и выпустил под брендом MazenX: дизайн уровней, логика прыжков и пушек, ИИ противников и релизная сборка.",
    "vlabel_bone": "MAZENX / 2D ЭКШЕН-ПЛАТФОРМЕР",
    "game_bone_topline": "02 — ИНДИ-ИГРА",
    "game_bone_title": "The Bone Runner",
    "game_bone_summary": "Хардкорный 2D-экшен на Unreal Engine, где игрок сражается со скелетами и рассчитывает тайминги для преодоления опасных ловушек подземелий.",
    "game_bone_long": "Плавная 2D-анимация, боевая система ближнего боя, поведенческий ИИ врагов и циклы активации ловушек.",
    "game_bone_contrib": "Разработал механику боя и перемещения, поведение противников, дизайн подземелий и сборки для Windows и Android.",
    "vlabel_addiction": "MAZENX / BLUEPRINTS",
    "game_addiction_topline": "03 — ИНДИ-ИГРА",
    "game_addiction_title": "Gambling Addiction",
    "game_addiction_summary": "Экспериментальная боевая арена на Blueprints в Unreal Engine, где случайные эффекты магических шаров меняют союзников, врагов и исход битвы.",
    "game_addiction_long": "Три режима сражений (Боты против ботов, Игрок против ботов, Боты против игроков) с динамически меняющимися сторонами конфликта.",
    "game_addiction_contrib": "Реализовал систему случайных событий на Blueprints, логику ИИ и архитектуру режимов игры.",
