    "studio_title": "MazenX 스튜디오<span class=\"accent-dot\">.</span>",
    "studio_note": "MazenX는 개인 인디 게임 개발 스튜디오입니다. 언리얼 엔진을 사용하여 독창적인 오리지널 게임을 기획, 개발하고 Windows 및 Android에 출시합니다.",
