    "game_kix_topline": "01 — 인디 액션 게임",
    "game_kix_title": "Crazy Kix",
    "game_kix_summary": "추격해오는 드론과 레이저 공격을 피하며 대포와 다이내믹 발판을 활용해 스테이지를 질주하는 스피디한 액션 플랫포머 게임.",
    "game_kix_long": "민첩한 캐릭터 조작감, 드론 AI 알고리즘, 레이저 기믹 및 인터랙티브 오브젝트를 갖추어 PC와 모바일 모두에서 몰입도 높은 플레이를 제공합니다.",
    "game_kix_contrib": "MazenX 브랜드로 단독 기획·개발·배포 완료: 레벨 디자인, 이동 물리, 적 AI 및 스토어 빌드 전담.",
    "vlabel_bone": "MAZENX / 2D 액션 플랫포머",
    "game_bone_topline": "02 — 인디 액션 게임",
    "game_bone_title": "The Bone Runner",
    "game_bone_summary": "던전의 해골 병사들과 전투를 벌이고 정밀한 타이밍으로 치명적인 함정을 돌파하는 2D 하드코어 액션 플랫포머.",
    "game_bone_long": "부드러운 2D 스프라이트 애니메이션, 근접 전투 시스템, 적 AI 패턴 및 던전 레벨 디자인을 언리얼 엔진으로 구현했습니다.",
    "game_bone_contrib": "전투 메커니즘, 적 캐릭터 행동 트리, 함정 시스템 및 Windows/Android 빌드 최적화를 수행했습니다.",
    "vlabel_addiction": "MAZENX / 블루프린트",
    "game_addiction_topline": "03 — 인디 게임",
    "game_addiction_title": "Gambling Addiction",
    "game_addiction_summary": "무작위 마법 구체의 효과로 아군과 적군이 뒤바뀌며 전장의 판도가 실시간으로 역전되는 언리얼 엔진 블루프린트 기반 아레나 배틀.",
    "game_addiction_long": "봇 대 봇, 플레이어 대 봇, 봇 대 플레이어의 3가지 대전 모드로 예측할 수 없는 다이내믹한 난전을 즐길 수 있습니다.",
    "game_addiction_contrib": "블루프린트를 통한 무작위 시스템 설계, AI 행동 패턴 및 게임 모드 구조를 완성했습니다.",
    "link_ms_store": "Microsoft Store ↗",
    "link_google_play": "Google Play ↗",
    "link_github": "GitHub ↗",
    "about_eyebrow": "개발 철학 및 접근 방식",
    "about_title": "첫 스케치부터<br>성공적인 <em>출시까지.</em>",
    "about_lede": "문제의 본질을 분석하고, 확장 가능한 아키텍처를 설계하며, 사용자에게 만족스러운 경험을 제공하여 프로덕션에 배포하는 전 과정을 즐깁니다.",
    "about_body": "엔터프라이즈, 헬스케어, SaaS, 교육 및 게임 분야를 아우르는 경험을 보유하고 있습니다. Flutter 기반 모바일 앱, NestJS 기반 백엔드, 언리얼 엔진 기반 게임을 개발하며 오픈 소스 생태계 기여와 후배 엔지니어 양성에도 힘쓰고 있습니다.",
