    "studio_eyebrow": "BAĞIMSIZ OYUN GELİŞTİRME",
    "studio_title": "MazenX Stüdyo<span class=\"accent-dot\">.</span>",
    "studio_note": "MazenX benim bağımsız oyun stüdyom: mobil ve Windows için özgün Unreal Engine oyunları tasarlıyor, geliştiriyor ve yayımlıyorum. Oyunları keşfedin ve tam açıklama ile katkılarımı görmek için her projeyi açın.",
    "studio_link": "LinkedIn'de MazenX'i ziyaret et ↗",
    "vlabel_kix": "MAZENX / UNREAL ENGINE",
    "game_kix_topline": "01 — BAĞIMSIZ OYUN",
    "game_kix_title": "Crazy Kix",
    "game_kix_summary": "Tehlikelerin üzerinden atlamak, topları kullanmak ve peşindeki dronlardan ve lazer saldırılarından kaçmak üzerine kurulu bir Unreal Engine aksiyon platform oyunu.",
    "game_kix_long": "Zorluk, hızı korumaktan gelir: dronlar oyuncuyu takip eder, lazerler tereddüdü cezalandırır, platformlar ve etkileşimli nesneler her bölümdeki rotayı şekillendirir. Proje; Android ve Windows sürümlerinde akıcı hareket, karşılaşma temposu, düşman davranışı, navigasyon ve çevresel oynanışı ele alır.",
    "game_kix_contrib": "Crazy Kix'i bağımsız stüdyom MazenX çatısı altında geliştirip yayımladım. Platform hareketi, etkileşimli butonlar ve toplar, dron karşılaşmaları ve lazer tehlikeleri dahil oynanışı ve bölüm deneyimini kurdum, ardından mobil ve Windows mağazaları için sürümleri hazırladım.",
    "vlabel_bone": "MAZENX / 2D AKSİYON PLATFORM",
    "game_bone_topline": "02 — BAĞIMSIZ OYUN",
    "game_bone_title": "The Bone Runner",
    "game_bone_summary": "Oyuncuların iskeletlerle savaştığı ve zindan tuzaklarını doğru zamanlamayla aştığı 2D bir Unreal Engine aksiyon platform oyunu.",
    "game_bone_long": "Her bölüm hareketi, zamanlamayı, dövüşü ve refleksleri sınar. Oyuncular tehlikeleri ve düşman karşılaşmalarını okumalı, ne zaman saldıracağına karar vermeli ve bunalmadan çıkışa ulaşmalıdır. Proje; Android ve Windows sürümleriyle 2D karakter hareketi, dövüş, düşman yapay zekâsı, animasyon, tuzak davranışı ve bölüm tasarımına odaklanır.",
    "game_bone_contrib": "Oyunu geliştirip bağımsız olarak yayımladım; temel hareket ve dövüş döngüsünü, iskelet karşılaşmalarını, tuzakları ve zindan bölümlerini kurdum, Android ve Windows sürümlerini hazırladım.",
    "vlabel_addiction": "MAZENX / BLUEPRINTS",
    "game_addiction_topline": "03 — BAĞIMSIZ OYUN",
    "game_addiction_title": "Gambling Addiction",
    "game_addiction_summary": "Rastgele sihirli top etkilerinin müttefikleri, düşmanları ve sonucu değiştirdiği, üç oyuncu ve yapay zekâ moduna sahip bir Blueprint arena oyunu.",
    "game_addiction_long": "Oyunun üç maç yapılandırması vardır: Bot vs Bots, Human vs Bot ve Bots vs Humans. Farklı sonuçlar değişen tarafları ve öngörülemeyen karşılaşmaları beraberinde getirir; doğrudan oynamak ya da yapay zekâ takımlarının değişen savaşa tepkisini izlemek mümkündür.",
    "game_addiction_contrib": "Blueprint kursundaki konsepti alıp rastgele sihirli top sonuçları, müttefik ve düşman ekleme ya da kaldırma etkileri ve üç oyun moduyla bağımsız olarak genişlettim; ardından oyun açıklamasını ve herkese açık proje materyallerini hazırladım.",
    "link_ms_store": "Microsoft Store ↗",
    "link_google_play": "Google Play ↗",
    "link_github": "GitHub ↗",
    "about_eyebrow": "NASIL ÇALIŞIRIM",
    "about_title": "İlk taslaktan<br><em>yayına.</em>",
    "about_lede": "Ürün yolculuğunun tamamından keyif alıyorum: problemi anlamak, mimariyi şekillendirmek, deneyimi inşa etmek ve onu üretime taşımak.",
    "about_body": "Çalışmalarım kurumsal yazılım, sağlık, SaaS, e-öğrenme, eğlence ve konum tabanlı ürünleri kapsıyor. Flutter ile çapraz platform uygulamalar, NestJS ile API'ler ve Unreal Engine ile oynanış sistemleri geliştiriyorum. Canlı ürünlerde çalıştım, farklı disiplinlerle iş birliği yaptım, pub.dev paketlerine katkıda bulundum ve kariyerinin başındaki geliştiricilere mentorluk yaptım.",
